#!/usr/bin/env node
// Every user-facing string in the views must have a Chinese translation.
// The catalogue is generated by hand, so this guard is what keeps a new string
// from silently showing English on a Chinese router.

import { readFileSync, readdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const viewDir = join(root, 'htdocs/luci-static/resources/view');
const poPath = join(root, 'po/zh_Hans/h5000m-pwmfan.po');

// Join "msgid" lines that continue on following quoted lines.
function parsePo(text) {
	const entries = new Map();
	let field = null;
	let buffer = '';
	let msgid = '';
	const flush = () => {
		if (field === 'msgstr' && msgid) entries.set(msgid, buffer);
		buffer = '';
	};
	for (const raw of text.split('\n')) {
		const line = raw.trimEnd();
		if (line.startsWith('msgid ')) {
			flush();
			field = 'msgid';
			msgid = JSON.parse(line.slice(6));
			buffer = '';
		}
		else if (line.startsWith('msgstr ')) {
			field = 'msgstr';
			buffer = JSON.parse(line.slice(7));
		}
		else if (line.startsWith('"') && field === 'msgid') {
			msgid += JSON.parse(line);
		}
		else if (line.startsWith('"') && field === 'msgstr') {
			buffer += JSON.parse(line);
		}
		else if (line === '' && field) {
			flush();
			field = null;
		}
	}
	flush();
	return entries;
}

// Collect every _('…') literal, including the concatenated form.
function strings(code) {
	const found = new Set();
	const call = /_\(\s*((?:'(?:[^'\\]|\\.)*'\s*\+?\s*)+)\)/g;
	let match;
	while ((match = call.exec(code))) {
		let text = '';
		const literal = /'((?:[^'\\]|\\.)*)'/g;
		let part;
		while ((part = literal.exec(match[1]))) text += eval("'" + part[1] + "'");
		if (text) found.add(text);
	}
	return found;
}

const catalogue = parsePo(readFileSync(poPath, 'utf8'));
const used = new Map();
for (const name of readdirSync(viewDir).filter((file) => file.endsWith('.js'))) {
	const code = readFileSync(join(viewDir, name), 'utf8');
	for (const text of strings(code)) {
		if (!used.has(text)) used.set(text, []);
		used.get(text).push(name);
	}
}

const problems = [];
for (const [text, files] of used) {
	if (!catalogue.has(text)) problems.push(`missing translation: ${JSON.stringify(text)} (${files.join(', ')})`);
	else if (!catalogue.get(text)) problems.push(`empty translation: ${JSON.stringify(text)} (${files.join(', ')})`);
}
for (const text of catalogue.keys()) {
	if (text && !used.has(text)) console.log(`note: unused catalogue entry ${JSON.stringify(text)}`);
}

if (problems.length) {
	console.log(`${problems.length} translation problem(s):`);
	for (const line of problems) console.log(` - ${line}`);
	process.exit(1);
}
console.log(`translations complete (${used.size} strings)`);
